import React,{useRef,useState,useMemo} from 'react';
import {useFrame} from '@react-three/fiber';
import * as THREE from 'three';
import {useTouch,TouchControls,Hud} from 'spider-touch';
const S=(f=440,t='sine',d=0.12,v=0.1)=>{try{const C=new(window.AudioContext||window.webkitAudioContext)();const o=C.createOscillator();const g=C.createGain();o.type=t;o.frequency.setValueAtTime(f,C.currentTime);g.gain.setValueAtTime(v,C.currentTime);g.gain.exponentialRampToValueAtTime(0.001,C.currentTime+d);o.connect(g);g.connect(C.destination);o.start();o.stop(C.currentTime+d);}catch(e){}};
const UP=[{id:'rate',n:'Overclock',d:'+25 percent fire rate',c:'#22d3ee'},{id:'twin',n:'Twin Shot',d:'+1 projectile',c:'#facc15'},{id:'pierce',n:'Piercing',d:'Bullets pierce +1',c:'#fb923c'},{id:'blade',n:'Orbit Blades',d:'+1 orbiting blade',c:'#e879f9'},{id:'magnet',n:'Magnet',d:'Bigger pickup range',c:'#4ade80'},{id:'hp',n:'Hull Plate',d:'+25 max hull',c:'#f87171'}];
const CC=['#22d3ee','#facc15','#e879f9'];
export default function GameComponent(){
const touch=useTouch();
const pr=useRef();const haloR=useRef();const trailR=useRef();const br=useRef();const shR=useRef();const bossR=useRef();const bossHalo=useRef();const lasR=useRef();const telR=useRef();const borderR=useRef();
const P=useRef({x:0,z:0,hp:100,max:100,xp:0,nxp:8,lvl:1,fire:0.32,ft:0,twin:1,pierce:0,blades:0,mag:3,shield:0,ct:0,combo:1,ctm:0,shock:0,wt:0});
const E=useRef(Array.from({length:30},()=>({a:false,t:0,x:0,z:0,hp:1,st:0,wt:0,dx:0,dz:0})));
const B=useRef(Array.from({length:30},()=>({a:false,x:0,z:0,dx:0,dz:0,p:0})));
const EB=useRef(Array.from({length:40},()=>({a:false,x:0,z:0,dx:0,dz:0,life:0})));
const G=useRef(Array.from({length:30},()=>({a:false,x:0,z:0,v:1})));
const K=useRef(Array.from({length:20},()=>({a:false,k:0,x:0,z:0})));
const PT=useRef(Array.from({length:60},()=>({a:false,x:0,y:0,z:0,vx:0,vy:0,vz:0,l:0})));
const eM=useRef([]);const bM=useRef([]);const ebM=useRef([]);const gM=useRef([]);const pM=useRef([]);const kM=useRef([]);
const shake=useRef(0);const lastA=useRef(0);const spawnT=useRef(0);const ebT=useRef(0);const trailT=useRef(0);
const [h,setH]=useState(100);const [mh,setMh]=useState(100);const [xp,setXp]=useState(0);const [nx,setNx]=useState(8);const [lv,setLv]=useState(1);
const [wv,setWv]=useState(1);const [sc,setSc]=useState(0);const [cb,setCb]=useState(1);const [gs,setGs]=useState('menu');const [ch,setCh]=useState([]);const [boss,setBoss]=useState(0);const [bm,setBm]=useState(0);const [msg,setMsg]=useState('');
const towers=useMemo(()=>{const a=[];for(let i=0;i<24;i++){const an=i/24*6.283;const r=19+Math.random()*4;a.push({x:Math.cos(an)*r,z:Math.sin(an)*r,w:1.4+Math.random()*1.8,h:4+Math.random()*10,d:1.4+Math.random()*1.8,c:i%3===0?'#22d3ee':(i%3===1?'#a855f7':'#ec4899')});}return a;},[]);
const burst=(x,z,n=8)=>{let f=0;for(const q of PT.current){if(!q.a&&f<n){q.a=true;q.x=x;q.y=0.6;q.z=z;const a=Math.random()*6.28;const s=3+Math.random()*5;q.vx=Math.cos(a)*s;q.vz=Math.sin(a)*s;q.vy=2+Math.random()*3;q.l=0.5;f++;}}};
const start=()=>{const p=P.current;p.x=0;p.z=0;p.hp=100;p.max=100;p.xp=0;p.nxp=8;p.lvl=1;p.fire=0.32;p.twin=1;p.pierce=0;p.blades=0;p.mag=3;p.shield=0;p.ct=0;p.combo=1;p.shock=0;p.wt=0;E.current.forEach(e=>e.a=false);B.current.forEach(b=>b.a=false);EB.current.forEach(b=>b.a=false);G.current.forEach(g=>g.a=false);K.current.forEach(k=>k.a=false);PT.current.forEach(q=>q.a=false);shake.current=0;spawnT.current=0;setH(100);setMh(100);setXp(0);setNx(8);setLv(1);setWv(1);setSc(0);setCb(1);setBoss(0);setMsg('');setGs('playing');S(660,'sawtooth',0.2);};
const lvlUp=()=>{const s=[...UP].sort(()=>Math.random()-0.5).slice(0,3);setCh(s);setGs('levelup');S(880,'sine',0.25);};
const pick=(u)=>{const p=P.current;if(u.id==='rate')p.fire=Math.max(0.09,p.fire*0.78);if(u.id==='twin')p.twin=Math.min(4,p.twin+1);if(u.id==='pierce')p.pierce++;if(u.id==='blade')p.blades=Math.min(4,p.blades+1);if(u.id==='magnet')p.mag+=2.2;if(u.id==='hp'){p.max+=25;p.hp=Math.min(p.max,p.hp+40);}S(990,'triangle',0.2);setCh([]);setGs('playing');};
const hurt=(d)=>{const p=P.current;if(gs!=='playing')return;if(p.shield>0){p.shield-=d;if(p.shield<0){d=-p.shield;p.shield=0;}else d=0;}if(d<=0)return;p.hp-=d;p.ct=0;p.combo=1;setCb(1);shake.current=0.5;burst(p.x,p.z,10);S(90,'sawtooth',0.25,0.15);setH(p.hp);if(p.hp<=0){setGs('over');S(60,'sawtooth',0.6,0.2);}};
const bossRef=useRef({a:false,x:0,z:-8,hp:600,max:600,ph:1,t:0,lt:0});
useFrame((st,dt)=>{
dt=Math.min(dt,0.033);const p=P.current;const t=st.clock.elapsedTime;
if(borderR.current){const pu=0.5+0.5*Math.sin(t*3.2);borderR.current.scale.setScalar(1+pu*0.012);borderR.current.material.emissiveIntensity=2.2+pu*2.4;}
if(gs==='menu'){st.camera.position.set(Math.sin(t*0.3)*15,13,Math.cos(t*0.3)*15);st.camera.lookAt(0,2,0);return;}
if(gs!=='playing')return;
const mx=touch.move.x,mv=touch.move.y;
const sp=9;p.x=THREE.MathUtils.clamp(p.x+mx*sp*dt,-13,13);p.z=THREE.MathUtils.clamp(p.z-mv*sp*dt,-13,13);
p.ctm-=dt;if(p.ctm<=0){p.combo=1;p.ct=0;setCb(1);}
if(touch.presses.a!==lastA.current){lastA.current=touch.presses.a;if(p.shock<=0){p.shock=6;shake.current=0.8;S(150,'sawtooth',0.4,0.2);burst(p.x,p.z,22);E.current.forEach(e=>{if(!e.a)return;const d=Math.hypot(e.x-p.x,e.z-p.z);if(d<7){e.hp-=3;e.x+=(e.x-p.x)/(d||1)*3;e.z+=(e.z-p.z)/(d||1)*3;}});const bs=bossRef.current;if(bs.a&&Math.hypot(bs.x-p.x,bs.z-p.z)<7)bs.hp-=25;}}
p.shock-=dt;
if(pr.current){pr.current.position.set(p.x,0.7,p.z);pr.current.rotation.y+=dt*(1+Math.hypot(mx,mv)*4);}
if(haloR.current){haloR.current.position.set(p.x,0.7,p.z);const s=2.4+Math.sin(t*5)*0.25;haloR.current.scale.setScalar(s);}
if(trailR.current){trailR.current.position.set(p.x-mx*1.4,0.55,p.z+mv*1.4);const f=1+Math.hypot(mx,mv)*1.6+Math.sin(t*22)*0.18;trailR.current.scale.set(1,f,1);trailR.current.rotation.y=Math.atan2(mx,-mv||0.001);trailT.current-=dt;if(Math.hypot(mx,mv)>0.15&&trailT.current<=0){trailT.current=0.03;for(const q of PT.current)if(!q.a){q.a=true;q.x=p.x-mx*1.2;q.y=0.55;q.z=p.z+mv*0.2;q.vx=-mx*2+(Math.random()-0.5);q.vz=mv*2+(Math.random()-0.5);q.vy=0.6;q.l=0.4;break;}}}
if(br.current)br.current.rotation.y-=dt*3;
if(shR.current){const e=6-p.shock;const s=e<0.6?e*16:Math.max(0,9.6-(e-0.6)*14);shR.current.position.set(p.x,0.15,p.z);shR.current.scale.setScalar(Math.max(0.01,s));shR.current.visible=p.shock>0&&s>0.1;}
p.ft-=dt;if(p.ft<=0){let bi=null,bd=1e9;E.current.forEach(e=>{if(!e.a)return;const d=Math.hypot(e.x-p.x,e.z-p.z);if(d<bd){bd=d;bi=e;}});const bs=bossRef.current;if(bs.a){const d=Math.hypot(bs.x-p.x,bs.z-p.z);if(d<bd){bd=d;bi=bs;}}if(bi&&bd<16){p.ft=p.fire;const base=Math.atan2(bi.x-p.x,bi.z-p.z);for(let i=0;i<p.twin;i++){const off=(i-(p.twin-1)/2)*0.14;for(const b of B.current)if(!b.a){b.a=true;b.x=p.x;b.z=p.z;b.dx=Math.sin(base+off);b.dz=Math.cos(base+off);b.p=p.pierce;break;}}S(700+Math.random()*200,'square',0.06,0.04);}}
spawnT.current-=dt;const alive=E.current.filter(e=>e.a).length;
if(spawnT.current<=0&&alive<4+wv*2&&!bossRef.current.a){spawnT.current=Math.max(0.3,1.4-wv*0.15);const sl=E.current.find(e=>!e.a);if(sl){sl.a=true;const r=Math.random();sl.t=r<0.5?0:(r<0.78?1:2);const a=Math.random()*6.28;sl.x=THREE.MathUtils.clamp(p.x+Math.cos(a)*11,-13,13);sl.z=THREE.MathUtils.clamp(p.z+Math.sin(a)*11,-13,13);sl.hp=sl.t===0?2+wv*0.4:(sl.t===1?3+wv*0.5:4+wv*0.6);sl.st=0;sl.wt=0;}}
if(!bossRef.current.a){p.wt+=dt;if(p.wt>18+wv*2){if(wv>=5){const bs=bossRef.current;bs.a=true;bs.hp=bs.max=600+wv*20;bs.ph=1;bs.t=0;setBoss(1);setBm(1);setMsg('RIFT WARDEN APPROACHES');setTimeout(()=>setMsg(''),2500);S(80,'sawtooth',0.8,0.2);}else{setWv(w=>w+1);p.wt=0;setMsg('WAVE '+(wv+1));setTimeout(()=>setMsg(''),1500);S(520,'triangle',0.3);}}}
for(const e of E.current){if(!e.a)continue;const dx=p.x-e.x,dz=p.z-e.z;const d=Math.hypot(dx,dz)||1;
if(e.t===0){e.x+=dx/d*3.2*dt;e.z+=dz/d*3.2*dt;}
else if(e.t===1){if(d>8){e.x+=dx/d*2.4*dt;e.z+=dz/d*2.4*dt;}else if(d<5){e.x-=dx/d*2*dt;e.z-=dz/d*2*dt;}}
else{if(e.st===0){e.x+=dx/d*2.2*dt;e.z+=dz/d*2.2*dt;e.wt+=dt;if(e.wt>1.6){e.st=1;e.wt=0.5;e.dx=dx/d;e.dz=dz/d;S(200,'sawtooth',0.2);}}else{e.wt-=dt;if(e.wt<=0){e.st=0;e.wt=0;}else{e.x+=e.dx*11*dt;e.z+=e.dz*11*dt;}}}
if(d<1.1){hurt(e.t===2?14:10);e.hp-=1;burst(e.x,e.z,5);if(e.hp<=0)e.a=false;}}
ebT.current-=dt;if(ebT.current<=0){ebT.current=1.1;for(const e of E.current){if(!e.a||e.t!==1)continue;const d=Math.hypot(p.x-e.x,p.z-e.z);if(d<13){for(const b of EB.current)if(!b.a){b.a=true;b.x=e.x;b.z=e.z;b.dx=(p.x-e.x)/d*6;b.dz=(p.z-e.z)/d*6;b.life=4;break;}}}}
const bs=bossRef.current;
if(bs.a){bs.t+=dt;const bd=Math.hypot(p.x-bs.x,p.z-bs.z)||1;const frac=bs.hp/bs.max;const nph=frac>0.66?1:(frac>0.33?2:3);if(nph!==bs.ph){bs.ph=nph;setMsg(nph===2?'WARDEN: BULLET RINGS':'WARDEN: LASER SWEEP');setTimeout(()=>setMsg(''),2000);S(120,'sawtooth',0.5,0.2);}setBm(frac);
if(bs.ph===1){bs.x+=Math.sin(Math.atan2(p.x-bs.x,p.z-bs.z))*1.6*dt;bs.z+=Math.cos(Math.atan2(p.x-bs.x,p.z-bs.z))*1.6*dt;bs.lt+=dt;if(bs.lt>3){bs.lt=0;for(let i=0;i<2;i++){const s=E.current.find(v=>!v.a);if(s){s.a=true;s.t=0;s.x=bs.x+(Math.random()-0.5)*4;s.z=bs.z+(Math.random()-0.5)*4;s.hp=3;}}}}
if(bs.ph===2){bs.lt+=dt;if(bs.lt>2.2){bs.lt=0;for(let i=0;i<12;i++){const a=i/12*6.28;for(const b of EB.current)if(!b.a){b.a=true;b.x=bs.x;b.z=bs.z;b.dx=Math.sin(a)*5;b.dz=Math.cos(a)*5;b.life=5;break;}}S(300,'square',0.3,0.12);shake.current=0.4;}}
if(bs.ph===3){bs.lt+=dt;const la=Math.atan2(p.x-bs.x,p.z-bs.z);if(bs.lt<1.2){if(telR.current){telR.current.visible=true;telR.current.position.set(bs.x,0.1,bs.z);telR.current.rotation.y=la;}}else{if(telR.current)telR.current.visible=false;if(lasR.current){lasR.current.visible=true;lasR.current.position.set(bs.x,0.4,bs.z);lasR.current.rotation.y=la;}const rel=Math.atan2(p.x-bs.x,p.z-bs.z);let dd=Math.abs(rel-la);if(dd>Math.PI)dd=6.28-dd;if(dd<0.12&&Math.hypot(p.x-bs.x,p.z-bs.z)<14)hurt(25*dt*3);if(bs.lt>2.4){bs.lt=0;if(lasR.current)lasR.current.visible=false;}}}else{if(lasR.current)lasR.current.visible=false;if(telR.current&&bs.ph!==3)telR.current.visible=false;}
if(Math.hypot(p.x-bs.x,p.z-bs.z)<1.6)hurt(20*dt*3);
if(bs.hp<=0){bs.a=false;setBoss(0);if(lasR.current)lasR.current.visible=false;if(telR.current)telR.current.visible=false;burst(bs.x,bs.z,30);S(100,'sawtooth',0.8,0.2);setSc(s=>s+500);setGs('win');}}
for(const b of B.current){if(!b.a)continue;b.x+=b.dx*20*dt;b.z+=b.dz*20*dt;if(Math.abs(b.x)>14||Math.abs(b.z)>14){b.a=false;continue;}let hit=false;for(const e of E.current){if(!e.a)continue;if(Math.hypot(b.x-e.x,b.z-e.z)<0.9){e.hp-=1;burst(b.x,b.z,3);S(900,'square',0.05,0.05);p.ct++;p.ctm=3;p.combo=1+Math.min(8,Math.floor(p.ct/8));setCb(p.combo);if(e.hp<=0){e.a=false;burst(e.x,e.z,8);setSc(s=>s+10*p.combo);for(const g of G.current)if(!g.a){g.a=true;g.x=e.x;g.z=e.z;g.v=e.t===2?3:(e.t===1?2:1);break;}if(Math.random()<0.06){for(const k of K.current)if(!k.a){k.a=true;k.k=Math.floor(Math.random()*3);k.x=e.x;k.z=e.z;break;}}}if(b.p>0)b.p--;else b.a=false;hit=true;break;}}if(!hit&&bs.a&&Math.hypot(b.x-bs.x,b.z-bs.z)<1.6){bs.hp-=1;burst(b.x,b.z,2);setSc(s=>s+2);if(b.p>0)b.p--;else b.a=false;}}
for(const b of EB.current){if(!b.a)continue;b.x+=b.dx*dt;b.z+=b.dz*dt;b.life-=dt;if(b.life<=0||Math.abs(b.x)>14||Math.abs(b.z)>14){b.a=false;continue;}if(Math.hypot(b.x-p.x,b.z-p.z)<0.7){b.a=false;hurt(8);}}
if(p.blades>0){const tt=t*3;for(let i=0;i<p.blades;i++){const a=tt+i/p.blades*6.28;const bx=p.x+Math.cos(a)*2.2,bz=p.z+Math.sin(a)*2.2;for(const e of E.current){if(e.a&&Math.hypot(bx-e.x,bz-e.z)<0.9){e.hp-=4*dt;if(e.hp<=0){e.a=false;setSc(s=>s+10);for(const g of G.current)if(!g.a){g.a=true;g.x=e.x;g.z=e.z;g.v=1;break;}}}}if(bs.a&&Math.hypot(bx-bs.x,bz-bs.z)<1.8)bs.hp-=20*dt;}}
for(const g of G.current){if(!g.a)continue;const d=Math.hypot(p.x-g.x,p.z-g.z);if(d<p.mag&&d>0.01){g.x+=(p.x-g.x)/d*10*dt;g.z+=(p.z-g.z)/d*10*dt;}if(d<0.9){g.a=false;p.xp+=g.v;setXp(p.xp);S(1200+Math.random()*400,'sine',0.08,0.06);if(p.xp>=p.nxp){p.xp-=p.nxp;p.nxp=Math.floor(p.nxp*1.4);p.lvl++;setLv(p.lvl);setNx(p.nxp);setXp(p.xp);lvlUp();}}}
for(const k of K.current){if(!k.a)continue;const d=Math.hypot(p.x-k.x,p.z-k.z);if(d<1.1){k.a=false;if(k.k===0){p.hp=Math.min(p.max,p.hp+30);setH(p.hp);S(600,'sine',0.2);}else if(k.k===1){p.shield=30;S(500,'triangle',0.3);}else{E.current.forEach(e=>{if(e.a){e.hp-=10;burst(e.x,e.z,5);}});if(bs.a)bs.hp-=80;shake.current=1;S(80,'sawtooth',0.6,0.2);}setSc(s=>s+5);}}
for(const q of PT.current){if(!q.a)continue;q.l-=dt;if(q.l<=0){q.a=false;continue;}q.x+=q.vx*dt;q.z+=q.vz*dt;q.y+=q.vy*dt;q.vy-=9*dt;if(q.y<0.05)q.y=0.05;}
E.current.forEach((e,i)=>{const m=eM.current[i];if(!m)return;m.visible=e.a;if(e.a){m.position.set(e.x,0.6,e.z);m.rotation.y+=dt*2;if(m.children[0])m.children[0].visible=e.t===0;if(m.children[1])m.children[1].visible=e.t===1;if(m.children[2])m.children[2].visible=e.t===2;if(m.children[3])m.children[3].scale.setScalar(2.1+Math.sin(t*6+i)*0.3);}});
B.current.forEach((b,i)=>{const m=bM.current[i];if(!m)return;m.visible=b.a;if(b.a)m.position.set(b.x,0.5,b.z);});
EB.current.forEach((b,i)=>{const m=ebM.current[i];if(!m)return;m.visible=b.a;if(b.a)m.position.set(b.x,0.5,b.z);});
G.current.forEach((g,i)=>{const m=gM.current[i];if(!m)return;m.visible=g.a;if(g.a){m.position.set(g.x,0.4+Math.sin(t*4+i)*0.15,g.z);m.rotation.y+=dt*4;}});
K.current.forEach((k,i)=>{const m=kM.current[i];if(!m)return;m.visible=k.a;if(k.a)m.position.set(k.x,0.5,k.z);});
PT.current.forEach((q,i)=>{const m=pM.current[i];if(!m)return;m.visible=q.a;if(q.a){m.position.set(q.x,q.y,q.z);m.scale.setScalar(Math.max(0.05,q.l*0.9));}});
if(bossR.current){bossR.current.visible=bs.a;if(bs.a){bossR.current.position.set(bs.x,1.2,bs.z);bossR.current.rotation.x+=dt*0.8;bossR.current.rotation.y+=dt*1.2;}}
if(bossHalo.current){bossHalo.current.visible=bs.a;if(bs.a){bossHalo.current.position.set(bs.x,1.2,bs.z);bossHalo.current.scale.setScalar(4.4+Math.sin(t*4)*0.4);}}
const sh=shake.current;shake.current=Math.max(0,sh-dt*1.5);
const ox=(Math.random()-0.5)*(sh*1.2),oz=(Math.random()-0.5)*(sh*1.2);
st.camera.position.lerp(new THREE.Vector3(p.x+ox*0.5,24,p.z+9+oz*0.5),0.18);st.camera.lookAt(p.x,0,p.z+1);st.camera.fov=58;st.camera.updateProjectionMatrix();
});
const hpFrac=Math.max(0,h/mh);
return(<group>
<color attach="background" args={['#05010f']}/><fog attach="fog" args={['#05010f',24,52]}/>
<hemisphereLight args={['#22d3ee','#4c1d95',0.7]}/><directionalLight position={[6,14,4]} intensity={1.2}/>
<mesh rotation-x={-Math.PI/2}><planeGeometry args={[34,34]}/><meshStandardMaterial color="#0a0620" roughness={0.9}/></mesh>
<gridHelper args={[30,30,'#22d3ee','#7c3aed']} position={[0,0.02,0]}/>
{towers.map((tw,i)=>(<group key={'tw'+i} position={[tw.x,0,tw.z]}>
<mesh position-y={tw.h/2}><boxGeometry args={[tw.w,tw.h,tw.d]}/><meshStandardMaterial color="#0b1026" emissive={tw.c} emissiveIntensity={0.55} roughness={0.6}/></mesh>
<mesh position-y={tw.h+0.25}><octahedronGeometry args={[0.35]}/><meshStandardMaterial color={tw.c} emissive={tw.c} emissiveIntensity={3}/></mesh>
